# Explore all color components and their shapes/distances in the test grid, for task inference
from collections import deque
components=[]
for r in range(25):
 for c in range(29):
  v=g[r][c]
  if v==8 or any((r,c) in x[2] for x in components): continue
  q=deque([(r,c)]); pts={(r,c)}
  while q:
   y,x=q.popleft()
   for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
    p=(y+dy,x+dx)
    if 0<=p[0]<25 and 0<=p[1]<29 and g[p[0]][p[1]]==v and p not in pts:
     pts.add(p);q.append(p)
  components.append((v,(min(y for y,x in pts),min(x for y,x in pts),max(y for y,x in pts),max(x for y,x in pts)),pts))
print([(v,box,len(pts)) for v,box,pts in components])

# component shape signatures normalized under rotations/reflections and same orientation
from collections import defaultdict
sigmap=defaultdict(list)
for v,b,pts in components:
 minr=min(r for r,c in pts);minc=min(c for r,c in pts)
 shape=tuple(sorted((r-minr,c-minc) for r,c in pts))
 sigmap[shape].append((v,len(pts),b,shape))
for sh,vals in sigmap.items():
 if len(vals)>1 and len({x[0] for x in vals})>1: print(vals)
